**A. `.claude/helpers/memory.cjs` — full JSON round-trip on every operation**

Every `get`, `set`, `delete`, and `keys` call reads the entire `memory.json` from disk. This is called from hooks that fire frequently.

```js
// CURRENT — disk read on every call
function loadMemory() {
  return JSON.parse(fs.readFileSync(MEMORY_FILE, 'utf-8'));
}
```

```js
// FIX — module-level cache, invalidated on write
let _cache = null;
let _cacheMtime = 0;

function loadMemory() {
  try {
    const mtime = fs.statSync(MEMORY_FILE).mtimeMs;
    if (_cache && mtime === _cacheMtime) return _cache;
    _cache = JSON.parse(fs.readFileSync(MEMORY_FILE, 'utf-8'));
    _cacheMtime = mtime;
    return _cache;
  } catch { return {}; }
}

function saveMemory(memory) {
  fs.mkdirSync(MEMORY_DIR, { recursive: true });
  fs.writeFileSync(MEMORY_FILE, JSON.stringify(memory, null, 2));
  _cache = memory;
  _cacheMtime = fs.statSync(MEMORY_FILE).mtimeMs;
}
```

**B. `.claude/helpers/metrics-db.mjs:261,285` — double directory traversal**

`syncMetrics()` calls `countFilesAndLines(moduleDir)` for each module, then calls `countFilesAndLines(V3_DIR)` again (line 285) for totals — traversing all the same files twice.

```js
// FIX — accumulate totals from per-module results
let totalFiles = 0, totalLines = 0;
for (const entry of entries) {
  const { files, lines } = countFilesAndLines(moduleDir);
  totalFiles += files;
  totalLines += lines;
  modules.push({ name: entry.name, files, lines, progress });
}
// Remove: const totalStats = countFilesAndLines(V3_DIR);
```

---

**A. `.claude/helpers/context-persistence-hook.mjs` — `pending-insights.jsonl` is append-only**

The file at `.claude-flow/data/pending-insights.jsonl` is written in append mode with no pruning in the code paths visible. Under active use this grows unboundedly. The existing `RETENTION_DAYS` env var controls transcript archive cleanup but does not affect this file.

```js
// Add a rotation guard when writing:
function appendInsight(entry) {
  const stat = fs.existsSync(PENDING_PATH) ? fs.statSync(PENDING_PATH) : null;
  if (stat && stat.size > 5 * 1024 * 1024) {  // 5 MB cap
    // Rotate: keep last N lines
    const lines = fs.readFileSync(PENDING_PATH, 'utf-8').split('\n').filter(Boolean);
    fs.writeFileSync(PENDING_PATH, lines.slice(-500).join('\n') + '\n');
  }
  fs.appendFileSync(PENDING_PATH, JSON.stringify(entry) + '\n');
}
```

**B. `.claude/helpers/learning-service.mjs:171-198` — HNSWIndex accumulates vector IDs**

`this.nextVectorId` increments monotonically and the Map keys are integer IDs. `remove()` deletes from `this.vectors` but if `_removeFromGraph(vectorId)` leaves stale neighbor references in `this.layers`, the layer arrays hold references to deleted vector IDs indefinitely — proportional to total insertions, not live count.

Ensure `_removeFromGraph` purges the vectorId from all neighbor lists in each layer, not just the entry point.

